INSERT INTO "legacy_csv_rows" VALUES(134,135,'1606','Execution of Sikh Guru Arjan Dev by the Mughals','Guru Arjan was arrested under the orders of the Mughal Emperor Jahangir and asked to convert to Islam. He refused, was tortured and executed in 1606 CE','https://en.wikipedia.org/wiki/Guru_Arjan#Death','','10','','{"America": "", "Europe": "", "Asia": "", "Africa": "", "China": "", "Discovery": "", "Britain": "", "France": "", "Greek": "", "India": "1.0", "Inventions": "", "MiddleEast": "", "prehistory": "", "Religion": "1.0", "Roman": "", "Royalty": "", "Russia": "", "Science": "", "SouthAmerica": "", "Wars": "", "World": ""}',1606);
INSERT INTO "legacy_csv_rows" VALUES(135,136,'1609','Kepler discovers that planets have elliptical orbits','Kepler discovered that the orbit of Mars was an ellipse. In 1609 he published Astronomia Nova, delineating his discoveries, which are now called Kepler''s first two laws of planetary motion.','','','6','','{"America": "", "Europe": "1.0", "Asia": "", "Africa": "", "China": "", "Discovery": "1.0", "Britain": "", "France": "", "Greek": "", "India": "", "Inventions": "", "MiddleEast": "", "prehistory": "", "Religion": "", "Roman": "", "Royalty": "", "Russia": "", "Science": "1.0", "SouthAmerica": "", "Wars": "", "World": ""}',1609);
