INSERT INTO "legacy_csv_rows" VALUES(274,275,'1976','Viking I lands on Mars',' Viking 1 (sent by NASA) touched down on Mars on July 20, 1976, the first successful Mars lander in history.','https://en.wikipedia.org/wiki/Viking_1','','8','','{"America": "", "Europe": "", "Asia": "", "Africa": "", "China": "", "Discovery": "", "Britain": "", "France": "", "Greek": "", "India": "", "Inventions": "", "MiddleEast": "", "prehistory": "", "Religion": "", "Roman": "", "Royalty": "", "Russia": "", "Science": "1.0", "SouthAmerica": "", "Wars": "", "World": "1.0"}',1976);
